using System.Collections.Immutable;
using System.Text.Json;
using AntMind.Contracts;
using AntMind.Core;
using AntMind.Programs;
using AntMind.Runtime;
using AntMind.Transport;

internal static class AntProgressionCheck {
    public static async Task Run(Action<bool,string> check) {
        var config=ContentLoader.LoadDefault() with {InitialResourceNodes=0,Combat=new()};
        var world=Simulation.Create(config,701);var xp=new AntExperienceRule();var explore=new ExplorationExperienceRule();
        var ant=world.Ants[0];var home=ant.Position;
        check(world.Ants.All(a=>a.Level==1 && a.Experience==0) && world.ExploredCells.Count==1,"all species start with independent level-one ants and no retroactive experience");
        var grown=xp.Apply(AntProgression.Record(world,ant.Id,30,"test-contribution"));
        check(grown.Ants[0] is {Level:2,Experience:30,MaxHealth:15,Health:12} && grown.Ants.Skip(1).All(a=>a.Level==1),"only the contributing ant is promoted and increased maximum health does not heal it");
        grown=xp.Apply(AntProgression.Record(grown,ant.Id,1000,"test-contribution"));
        check(grown.Ants[0] is {Level:3,Experience:120,MaxHealth:18,Health:12},"large experience gains reach but never exceed level three");
        var full=xp.Apply(AntProgression.Record(grown,ant.Id,10,"test-contribution"));
        check(full.Ants[0].Level==3 && full.Ants[0].Experience==120 && full.Ants[0].CompletedWork==3,"elite ants retain a bounded XP bar and continue recording useful work");
        var walked=world with {Ants=world.Ants.Select((a,i)=>i<2?a with {Position=new(home.X+1000,home.Y)}:a).ToImmutableArray()};
        walked=xp.Apply(explore.Apply(walked));
        check(walked.Ants[0].Experience==1 && walked.Ants[1].Experience==0,"new-cell exploration is awarded once in stable ant-ID order");
        var revisited=xp.Apply(explore.Apply(walked));
        check(revisited.Ants[0].Experience==1 && revisited.ExploredCells.Count==2,"standing still, revisits and shared paths cannot farm exploration XP");
        var mover=new MovementRule();var destination=new Point(home.X+10000,home.Y);
        var rookie=mover.Apply(world with {Ants=[ant with {Target=destination,Intent=AntAction.Move}]});
        var elite=mover.Apply(grown with {Ants=[grown.Ants[0] with {Target=destination,Intent=AntAction.Move}]});
        check(elite.Ants[0].Position.X-home.X==250 && rookie.Ants[0].Position.X-home.X==200 && grown.CarryCapacity(AntSpeciesIds.Hauler)==1,"rank improves actual movement without bypassing the separate payload upgrade cap");
        var action=new ProductionActionRule();var source=world.Objects.All<SourceView>().First(x=>x.ItemType==FoodTypes.Fruit);
        var harvesting=action.Apply(world with {Tick=1,Ants=[ant with {Position=source.Position,Intent=AntAction.Harvest,Production=new(source.Id,Quantity:1)}]});
        harvesting=xp.Apply(harvesting);
        check(harvesting.Ants[0].Experience==1 && ((SourceView)harvesting.Objects.Find("source",source.Id)!).Amount==source.Amount-1,"source harvesting earns experience only after an actual resource transfer");
        var failed=action.Apply(harvesting with {Tick=2,Ants=[harvesting.Ants[0] with {Intent=AntAction.Harvest}]});
        failed=xp.Apply(failed);
        check(failed.Ants[0].Experience==1,"failed cooldown and capacity attempts do not produce experience");
        var carrying=ant with {Experience=29,Carry=1,Intent=AntAction.Deliver,CargoTracked=true,CargoCredits=[new(1,1)]};
        var delivery=xp.Apply(new InteractionRule().Apply(world with {Tick=1,Ants=[carrying]}));
        check(delivery.Ants[0] is {Level:2,Experience:30,Carry:0} && delivery.FirstAdmissionPoints==1,"delivery promotion survives local interaction builders and occurs only on first food admission");
        var returned=xp.Apply(new InteractionRule().Apply(delivery with {Tick=20,Ants=[delivery.Ants[0] with {Carry=1,CargoCredits=[],CargoTracked=true,Intent=AntAction.Deliver}]}));
        check(returned.Ants[0].Experience==30 && returned.FirstAdmissionPoints==1,"withdrawing, dropping and redelivering already credited cargo cannot farm XP");
        var soldier=ant with {Species=AntSpeciesIds.Soldier,Level=3,Experience=120,Health=40,MaxHealth=60,Intent=AntAction.Attack,AttackTargetId=1};
        var fight=world with {Objects=world.Objects.Put(new EnemyView(1,new(home.X+1000,home.Y),30,30,1)),Ants=[soldier]};
        fight=new CombatRule().Apply(fight);
        check(((EnemyView)fight.Objects.Find("enemy",1)!).Health==21 && fight.PendingExperience.Sum(e=>e.Amount)==1,"elite soldiers deal their increased actual damage and valid hits create one XP event");
        var killed=new CombatRule().Apply(world with {Objects=world.Objects.Put(new EnemyView(1,new(home.X+1000,home.Y),1,1,1)),Ants=[soldier]});
        check(killed.PendingExperience.Sum(e=>e.Amount)==6 && killed.EnemiesDefeated==1,"a kill grants hit and kill credit exactly once");
        var invalid=new CombatRule().Apply(killed with {Tick=20,PendingExperience=[],Ants=[killed.Ants[0] with {Intent=AntAction.Attack}]});
        check(invalid.PendingExperience.IsEmpty,"attacking an already dead target never creates experience");
        var chef=ant with {Species=AntSpeciesIds.Builder,Level=2,Experience=30,Health=16,MaxHealth=20,Intent=AntAction.Work,Production=new(1)};
        var site=new BuildingView(1,home,"workshop") {Store=new FoodStore().Add(FoodTypes.Wood,12)};
        var labor=world with {NetworkLevel=2,Objects=world.Objects.Put(site),Ants=[chef]};var work=new WorkRule();
        for(var tick=1;tick<=4;tick++)labor=xp.Apply(work.Apply(labor with {Tick=tick}));
        check(((BuildingView)labor.Objects.Find("building",1)!).ConstructionWork==10 && labor.Ants[0].Experience==31 && labor.Ants[0].WorkRateRemainder==0,"fractional work bonuses deterministically produce ten real work units in four ticks and one XP");
        var last=world with {NetworkLevel=2,Objects=world.Objects.Put(site with {ConstructionWork=199}),Ants=[chef]};
        last=work.Apply(last with {Tick=1});
        check(last.PendingExperience.Single().Amount==1,"the final construction tick rewards actual remaining work rather than unused boosted capacity");
        var waiting=work.Apply(world with {NetworkLevel=2,Objects=world.Objects.Put(site with {Phase="ready"}),Ants=[chef]});
        check(waiting.PendingExperience.IsEmpty,"empty stations and invalid labor cannot farm work XP");
        var self=AntDslCompiler.Compile("memory[0]=ant_level; memory[1]=experience; memory[2]=experience_to_next; memory[3]=work_percent; wait();");
        var perception=new Perception(1,1,home,home,0,null,128,128,[]) {Level=2,Experience=35,ExperienceToNext=85,WorkPercent=125};
        var decision=self.Execute(perception,new(64));
        check(decision.Error is null && decision.Memory.Take(4).SequenceEqual(new[]{2,35,85,125}),"shared species programs can branch on their own individual rank and experience");
        var invalidConfig=false;try{(config with {Veterancy=new() {Thresholds=[0,30,20]}}).Validate();}catch(ArgumentException){invalidConfig=true;}
        check(invalidConfig,"progression content validates exactly three ordered levels");

        var directory=Path.Combine(Directory.GetCurrentDirectory(),"artifacts","progression-checks",Guid.NewGuid().ToString("N"));
        var catalog=new SpeciesProgramCatalog(config.AntTypes.Select(t=>t.Id));
        var checkpoint=world with {Objects=world.Objects.Put(grown.Ants[0]),ExploredCells=walked.ExploredCells};
        SavedGames.Write(directory,"elite",new(SavedGames.Format,Protocol.Version,checkpoint,catalog.Export()));
        var loaded=SavedGames.Read(directory,"elite");
        check(loaded.World.Ants[0] is {Level:3,Experience:120} && loaded.World.ExploredCells.SetEquals(checkpoint.ExploredCells),"full checkpoints preserve rank, XP and exploration anti-farming state");
        SavedGames.Write(directory,"legacy-v2",new(2,13,world,catalog.Export()));
        var migrated=SavedGames.Read(directory,"legacy-v2");
        check(migrated.Format==SavedGames.Format && migrated.Protocol==Protocol.Version && migrated.World.Ants.All(a=>a.Level==1 && a.Experience==0) && migrated.World.ExploredCells.Count==1,"version-two checkpoints migrate without fabricating prior experience");
        await using var session=new GameSession(config,701,savesPath:directory);
        var console=new CommandConsole((r,ct)=>Gateway.DispatchAsync(session,r,ct));
        var before=await session.ObserveAsync();
        check((await console.ExecuteAsync("help")).Contains("execute") && (await console.ExecuteAsync("catalog")).Contains("AntLevels"),"local console exposes current operations and level definitions");
        var missing=JsonDocument.Parse(await console.ExecuteAsync("inspect source 999999")).RootElement;
        check(missing.GetProperty("Error").GetString()=="object_not_found" && (await session.ObserveAsync()).Revision==before.Revision,"console inspection keeps discovery permissions and read-only queries do not advance revision");
        check((await console.ExecuteAsync("execute SetMinimumReserve {\"value\":20}")).Contains("true") && (await session.ObserveAsync()).MinimumReserve==20,"generic console commands execute through the actor with observed revision and world identity");
        check((await console.ExecuteAsync("step 3")).StartsWith("ok:") && (await session.ObserveAsync()).Tick==3,"console stepping advances the shared live world rather than a duplicate simulator");
        check((await console.ExecuteAsync("step 1001")).StartsWith("error:") && (await console.ExecuteAsync("execute SetMinimumReserve {\"typo\":1}")).StartsWith("error:"),"console rejects excessive steps and malformed command options without changes");
        await console.ExecuteAsync("save console");var oldId=(await session.ObserveAsync()).WorldId;await console.ExecuteAsync("step 2");await console.ExecuteAsync("load console");
        var restored=await session.ObserveAsync();
        check(restored.Tick==3 && restored.Paused && restored.WorldId!=oldId && (await console.ExecuteAsync("step")).StartsWith("ok:"),"console load restores the checkpoint and subsequent commands use the new world instance");
        var apply=Path.Combine(directory,"shared ant.ant");await File.WriteAllTextAsync(apply,"memory[0]=ant_level; wait();");
        check((await console.ExecuteAsync("apply scout \""+apply+"\"")).Contains("true"),"console loads quoted local source paths into the shared species slot");
        await console.ExecuteAsync("step");
        check((await session.ObserveAsync()).Ants.Where(a=>a.Species==AntSpeciesIds.Scout).All(a=>a.Memory[0]==a.Level),"console-applied programs read live individual levels at the normal tick boundary");
        var raw=await console.ExecuteAsync("ant 1");
        check(raw.Contains("Experience") && raw.Contains("CompletedWork"),"individual console inspection includes rank, work count and diagnostic state");
        await using var promoted=new GameSession(config,702,savesPath:directory);
        async Task<CommandResult> Submit(CommandKind kind,string key="",int group=0,int id=0) {var s=await promoted.ObserveAsync();return await promoted.ExecuteAsync(new(Guid.NewGuid(),s.Revision,kind,Reason:"rank persistence") {ExpectedWorldId=s.WorldId,Key=key,GroupId=group,AntId=id,Name="squad"});}
        await Submit(CommandKind.LoadGame,"elite");await Submit(CommandKind.CreateGroup);await Submit(CommandKind.AssignAnt,group:1,id:1);
        var view=await promoted.ObserveAsync();
        await promoted.ExecuteAsync(new(Guid.NewGuid(),view.Revision,CommandKind.ApplyProgram,Reason:"rank persistence",ProgramSource:"wait();") {ExpectedWorldId=view.WorldId});
        await Submit(CommandKind.Step);
        check((await promoted.ObserveAsync()).Ants[0] is {Level:3,Experience:120},"assignment changes and species program replacements preserve individual veterancy");
    }
}
